<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch, nextTick } from 'vue';
import { Plus, Upload, Search, ArrowRight, ArrowLeft, Sparkles, UserRound, Users, Images, Box, Check, X, Download, Settings2, Play, Layers, RefreshCw, Copy, Trash2, Pencil, Filter } from 'lucide-vue-next';
import UiButton from './UiButton.vue'; import UiBadge from './UiBadge.vue'; import UiDialog from './UiDialog.vue'; import RoomArt from './RoomArt.vue'; import AnnotationEditor from './AnnotationEditor.vue';
import AnnotationJob from './AnnotationJob.vue';
import UnassignedMedia from './UnassignedMedia.vue';
import ModelsPage from './ModelsPage.vue';
import TestPage from './TestPage.vue';
import DeployPage from './DeployPage.vue';
import AnalyticsPage from './AnalyticsPage.vue';
import { getPreview, batchColumn } from '../previewState.js';
import { liveAnnotate, loadBoard, loadSource, loadAssignment, loadReview, api as liveApi } from '../api/annotate.js';
import { FILTERS, loadDataset, loadVersions, datasetApi, recipeOf } from '../api/dataset.js';
import { loadTraining, trainApi, startKey, progressLine } from '../api/train.js';
const props = defineProps({page:String,project:Object,openAssignment:Number,openUpload:Number}); const emit=defineEmits(['navigate','create','opened','opened-upload']);
// Annotate reads the backend (api/annotate.js); the pages not connected yet keep the sample store.
const live=ref(null);
const LIVE_PAGES=['annotate','dataset','versions','train','models','test','deploy','analytics'];
const state=computed(()=>LIVE_PAGES.includes(props.page)&&live.value?live.value:getPreview(props.project?.ref?`real:${props.project.ref}`:props.project?.id));
// The connected pages load from the backend when they open (after setup: they read refs declared below).
function syncLive(){if(!(LIVE_PAGES.includes(props.page)&&props.project?.ref))return;if(!live.value||live.value.ref!==props.project.ref)live.value=liveAnnotate(props.project.ref);if(props.page==='annotate')loadBoard(live.value).then(openWanted).catch(liveError);else if(props.page==='dataset')refreshDataset(1);else if(props.page==='train')loadTrain();else if(!['models','test','deploy','analytics'].includes(props.page))loadVersions(live.value).catch(liveError);}
watch(()=>[props.page,props.project?.ref],syncLive);onMounted(syncLive);
async function refreshLive(){if(!live.value)return;await loadBoard(live.value);if(batch.value?.kind==='assignment'){const b=live.value.batches.find(x=>x.id===batch.value.id)||batch.value;batch.value=await loadAssignment(live.value,b);}if(reviewMode.value)await loadReview(live.value);}
function liveError(e){message.value=e.message;}
// Drag and drop on the board (asked for by the user on 2026-10-16). A drop runs the same backend step as the buttons:
// Unassigned→Annotating opens the batch on "Label with your team"; Annotating→In review submits it; In review→Dataset
// accepts it (after a confirmation); In review→Annotating sends it back and Annotating or In review→Unassigned rejects
// it (both with a reason). The Dataset is final, and a step is never skipped.
const dragging=ref(null);const dropOver=ref('');const moveDialog=ref(null);const moveReason=ref('');const moveBusy=ref(false);const choicesMode=ref('');
function dropRefusal(b,to){const from=batchColumn(b);if(!b||from===to)return '';
  if(from==='Dataset')return 'An accepted batch is final: its labels are approved and locked.';
  if(from==='Unassigned')return to==='Annotating'?'':'Give the batch to a labeller first: drop it on Annotating.';
  if(from==='Annotating')return to==='Dataset'?'A batch is reviewed before it enters the dataset: drop it on In review first.':'';
  return '';}
function dragStart(b,event){dragging.value=b;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',b.id);}
function dragEnd(){dragging.value=null;dropOver.value='';}
function dragOver(column,event){if(!dragging.value)return;event.preventDefault();dropOver.value=column;event.dataTransfer.dropEffect=dropRefusal(dragging.value,column)?'none':'move';}
async function dropOn(column){const b=dragging.value;dragEnd();if(!b||batchColumn(b)===column)return;const refused=dropRefusal(b,column);if(refused){message.value=refused;return;}
  if(!live.value){message.value='Preview only: a move is not saved here.';return;}
  message.value='';const from=batchColumn(b);
  if(from==='Unassigned'){choicesMode.value='team';await chooseBatch(b);return;}
  if(from==='Annotating'&&column==='In review')return moveNow(b,'return',{},`${b.name} is submitted for review.`);
  moveReason.value='';
  moveDialog.value=column==='Dataset'?{b,action:'accept',title:'Accept this batch',text:`The labels of ${b.name} are approved and locked, and its photos enter the dataset. This cannot be undone.`,reason:false,button:'Accept'}
    :column==='Annotating'?{b,action:'send-back',title:'Send back to the labeller',text:`${b.name} goes back to ${b.assignee} to label again.`,reason:true,button:'Send back'}
    :{b,action:'reject',title:'Reject this assignment',text:`${b.name} is closed without using its labels: they are kept, never enter a dataset version, and its photos go back to Unassigned.`,reason:true,button:'Reject'};}
async function moveNow(b,action,body,said){moveBusy.value=true;try{await liveApi.assignmentAction(live.value.ref,b.number,action,body);moveDialog.value=null;await refreshLive();tell(said);}
  catch(e){if(moveDialog.value)moveDialog.value.error=e.message;else message.value=e.message;}finally{moveBusy.value=false;}}
function confirmMove(){const d=moveDialog.value;if(!d||(d.reason&&!moveReason.value.trim()))return;
  moveNow(d.b,d.action,d.reason?{reason:moveReason.value.trim()}:{},d.action==='accept'?`${d.b.name} is accepted: its photos are in the dataset.`:d.action==='send-back'?`${d.b.name} is sent back to its labeller.`:`${d.b.name} is rejected; its photos are back in Unassigned.`);}
// An assignment a link names (a notification, an e-mail's button): opened once the board is loaded.
// After an upload, its batch opens on "Choose how to label this batch".
async function openUploaded(){const id=props.openUpload;if(!id||!live.value||props.page!=='annotate')return;emit('opened-upload');const b=live.value.batches.find(x=>x.kind==='upload'&&x.source===String(id));if(b)await chooseBatch(b);}
// A new assignment: its job page, or the editor at once ("Label manually", Auto Label).
function onAssigned(job,opts){batch.value=job;view.value='job';refreshLive().then(()=>{if(!opts?.edit)return;const images=state.value.images.filter(i=>i.batchId===job.id);if(images.length)openEditor(images.find(i=>!i.labelled)||images[0]);}).catch(liveError);}
async function openWanted(){if(props.openUpload&&!props.openAssignment)return openUploaded();const n=props.openAssignment;if(!n||!live.value||props.page!=='annotate')return;emit('opened');const b=live.value.batches.find(x=>x.kind==='assignment'&&x.number===n);if(b)await chooseBatch(b);else message.value=`Assignment ${n} is not on this project's board, or it is not yours to open.`;}
watch(()=>props.openAssignment,n=>{if(n&&live.value&&!live.value.loading&&live.value.ref===props.project?.ref)openWanted();});
const insight=computed(()=>props.page==='annotate'&&live.value?{images:props.project?.images??0,accepted:live.value.counts.ready+live.value.counts.trained_on,annotations:live.value.counts.to_approve+live.value.counts.ready+live.value.counts.trained_on,toLabel:live.value.counts.to_label,live:true}:{images:state.value.images.length,accepted:accepted.value,annotations:annotations.value,toLabel:state.value.images.filter(i=>i.state==='Unlabeled').length,live:false});
async function renameBatch(){const name=draft.value.trim();if(!name){error.value='Enter a batch name.';return;}if(live.value&&props.page==='annotate'){try{if(batch.value.kind==='assignment')await liveApi.updateAssignment(live.value.ref,batch.value.number,{name});else await liveApi.renameUpload(live.value.ref,batch.value.source,name);batch.value.name=name;modal.value='';tell('Batch renamed');await loadBoard(live.value);}catch(e){error.value=e.message;}return;}batch.value.name=name;modal.value='';tell('Batch renamed');}
const view=ref('board');const stateMode=ref('Populated');const query=ref('');const filter=ref('All');const modal=ref('');const draft=ref('');const message=ref('');const error=ref('');const picked=ref([]);const grid=ref(true);const overlays=ref(true);
const batch=ref(null);const editor=ref(false);const method=ref('');const model=ref('SAM 3 · masks');const prompt=ref('Outline room walls, windows and doors');const autoReady=ref(false);const modelTab=ref('Foundation models');const assignee=ref('Demo labeller');const reviewMode=ref(false);
const classTab=ref('Classes');const color=ref('#8b5cf6');const editing=ref(-1);const locked=ref(false);
const versionStep=ref(1);const versionName=ref('Version 1');const orient=ref(true);const resize=ref(true);const dimension=ref(640);const augmentation=ref(false);const split=ref('train_val');
const modelView=ref('My models');const taskFilter=ref('All tasks');const engine=ref('Custom training');const architecture=ref('RF-DETR');const size=ref('Small');const epochs=ref(50);const trainingStep=ref(1);const activeVersion=ref('');const resultReady=ref(false);const confidence=ref(0.5);const testSample=ref(false);const codeLang=ref('Python');const deployMode=ref('Cloud API');const activeLimit=ref(100);const activeConfidence=ref(0.4);const ruleClass=ref('wall');const source=ref('Production model');
const catalogue=[{name:'SAM 3',task:'Instance segmentation',description:'Promptable object masks and polygons.'},{name:'SAM 2',task:'Instance segmentation',description:'Box and point guided segmentation.'},{name:'Qwen VL',task:'Text prompting',description:'Visual questions and image descriptions.'},{name:'Florence-2',task:'Text prompting',description:'Captioning, detection and grounding.'},{name:'CLIP',task:'Classification',description:'Image and text similarity.'},{name:'YOLO-World',task:'Object detection',description:'Open vocabulary object detection.'},{name:'DocTR',task:'OCR',description:'Document text recognition.'},{name:'EasyOCR',task:'OCR',description:'Text recognition across languages.'}];
const filteredModels=computed(()=>catalogue.filter(m=>(taskFilter.value==='All tasks'||m.task===taskFilter.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())));
const images=computed(()=>props.page==='dataset'&&live.value&&props.project?.ref?state.value.images.filter(i=>i.batchId==='dataset'):state.value.images.filter(i=>(filter.value==='All'||i.state===filter.value)&&i.name.toLowerCase().includes(query.value.toLowerCase())));
const accepted=computed(()=>state.value.images.filter(i=>i.state==='Accepted'&&i.shapes.length>0).length);
const annotations=computed(()=>state.value.images.reduce((n,i)=>n+i.shapes.length,0));
const counts=computed(()=>state.value.classes.map(c=>({...c,count:state.value.images.reduce((n,i)=>n+i.shapes.filter(s=>s.kind===c.name).length,0)})));
const catalogVisible=computed(()=>stateMode.value!=='Empty');
watch(()=>props.page,()=>{view.value='board';query.value='';filter.value='All';message.value='';stateMode.value='Populated';});
function tell(text){message.value=text+(LIVE_PAGES.includes(props.page)&&live.value?'':' · Local preview only.');}
function openModal(name,value=''){modal.value=name;draft.value=value;error.value='';}
function openEditor(image){if(!state.value.images.length){tell('Add an image first');return;}state.value.selectedImage=image?.id||state.value.images[0].id;editor.value=true;}
async function chooseBatch(value){autoReady.value=false;if(live.value&&props.page==='annotate'){try{if(value.kind==='assignment'){batch.value=await loadAssignment(live.value,value);view.value='job';}else{await loadSource(live.value,value);batch.value=value;view.value='choices';}}catch(e){liveError(e);}return;}batch.value=value;view.value=batchColumn(value)==='Unassigned'?'choices':'job';}
async function goAuto(){modal.value='';emit('navigate','annotate');await nextTick();batch.value=state.value.batches[0]||null;view.value='auto';}
function beginManual(){if(batch.value){batch.value.status='Annotating';batch.value.assignee='Me';}view.value='job';}
function addClass(){const name=draft.value.trim();if(!name){error.value='Enter a name.';return;}if(classTab.value==='Tags'){if(!state.value.tags.includes(name))state.value.tags.push(name);}else {if(state.value.classes.some((c,i)=>c.name===name&&i!==editing.value)){error.value='This class already exists.';return;}if(editing.value>=0){const old=state.value.classes[editing.value].name;state.value.images.forEach(i=>i.shapes.forEach(s=>{if(s.kind===old)s.kind=name;}));state.value.classes[editing.value]={name,color:color.value};}else state.value.classes.push({name,color:color.value});}modal.value='';tell('Definition saved');}
function autoLabel(){if(!prompt.value.trim()){tell('Add a description before generating a preview');return;}autoReady.value=true;}
function applyAuto(){if(live.value&&props.page==='annotate'){tell('Auto label: coming soon. No labels were changed.');return;}state.value.images.filter(i=>(!batch.value||i.batchId===batch.value.id)&&i.state!=='Accepted').forEach(i=>{i.shapes=[{id:Date.now(),kind:state.value.classes[0]?.name||'wall',corner:'room',points:[[178,48],[460,48],[460,217],[178,217]]}];i.state='In review';});if(batch.value)batch.value.status='In review';tell('Sample annotations added to review queue');view.value='board';}
function markBatch(){const group=state.value.images.filter(i=>i.batchId===batch.value?.id);if(!group.length||group.some(i=>!i.shapes.length&&!i.noObjects)){tell('Label every image or mark no objects before accepting the batch');return;}group.forEach(i=>i.state='Accepted');batch.value.status='Dataset';view.value='board';tell('Batch accepted locally');}
async function makeVersion(){if(live.value&&props.page==='versions'){if(!versionName.value.trim()){tell('Enter a version name');return;}vBusy.value=true;try{const v=await datasetApi.publish(live.value.ref,{kind:split.value,title:versionName.value.trim(),recipe:recipeOf({resize:resize.value,dimension:dimension.value,augmentation:augmentation.value})});tell(` created:  photos`);view.value='board';versionStep.value=1;await loadVersions(live.value);}catch(e){tell(e.message);}finally{vBusy.value=false;}return;}if(!versionName.value.trim()){tell('Enter a version name');return;}state.value.versions.unshift({id:Date.now(),name:versionName.value,images:accepted.value,split:split.value,resize:resize.value?dimension.value:'Original',orient:orient.value,augmentation:augmentation.value});view.value='board';versionStep.value=1;tell('Version configuration saved');}
function train(){const run={id:Date.now(),name:`${architecture.value} ${size.value}`,version:activeVersion.value||'Sample version',epochs:epochs.value,status:'Complete (simulated)',accuracy:0.89};state.value.runs.unshift(run);state.value.models.unshift(run);modal.value='';trainingStep.value=1;tell('Simulated training result added; no job was started');}
function downloadCsv(){const lines=['class,count',...counts.value.map(c=>`"${c.name.replaceAll('"','""')}",${c.count}`)];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='preview-class-counts.csv';a.click();URL.revokeObjectURL(url);}
const code=computed(()=>codeLang.value==='Python'?'# Illustrative only: replace with an approved API contract\n# No credentials belong in frontend source\nresult = client.predict(image="room.jpg", model="YOUR_MODEL")':codeLang.value==='JavaScript'?'// Illustrative only; existing API integration is pending\nconst result = await approvedClient.predict(file);':'# Illustrative contract placeholder\n# Supply the approved endpoint and session authentication');
async function copyCode(){try{await navigator.clipboard.writeText(code.value);tell('Example copied');}catch{tell('Clipboard unavailable; select and copy the example');}}
// ── Dataset and Versions, connected (api/dataset.js) ──
const dsFilters=reactive({...FILTERS});const modalTargets=ref([]);const vPreview=ref(null);const vBusy=ref(false);
async function refreshDataset(page){if(!live.value)return;try{await loadDataset(live.value,{q:query.value,status:filter.value,filters:dsFilters,page:page||live.value.dataset?.page||1});picked.value=picked.value.filter(id=>state.value.images.some(i=>i.id===id&&i.batchId==='dataset'));}catch(e){liveError(e);}}
let dsTimer=null;watch([query,filter],()=>{if(props.page!=='dataset'||!live.value)return;clearTimeout(dsTimer);dsTimer=setTimeout(()=>refreshDataset(1),300);});
function resetFilters(){Object.assign(dsFilters,FILTERS);if(props.page==='dataset'&&live.value)refreshDataset(1);}
async function tagPicked(){const tag=draft.value.trim();if(!tag){error.value='Enter a tag.';return;}if(live.value&&props.page==='dataset'){try{const r=await datasetApi.tag(live.value.ref,picked.value,{add:tag});modal.value='';tell(r.full?`Tag added to ${r.changed}; ${r.full} already carry 20 tags`:`Tag added to ${r.changed} images`);await refreshDataset();}catch(e){error.value=e.message;}return;}state.value.images.filter(i=>picked.value.includes(i.id)).forEach(i=>{if(!i.tags.includes(tag))i.tags.push(tag)});modal.value='';tell('Tags added');}
async function toggleGolden(image){try{const r=await datasetApi.golden(live.value.ref,image.id,!image.golden);image.golden=r.golden;tell(r.golden?`${image.name} is in the golden set`:`${image.name} left the golden set`);}catch(e){liveError(e);}}
async function deleteTargets(){if(!draft.value.trim()){error.value='Give the reason for the deletion.';return;}try{const r=await datasetApi.remove(live.value.ref,modalTargets.value,draft.value);modal.value='';picked.value=[];tell(`${r.deleted} photo${r.deleted===1?'':'s'} deleted`+(r.affected_versions.length?`; the versions that held them keep them: ${r.affected_versions.join(', ')}`:''));await refreshDataset();}catch(e){error.value=e.message;}}
async function loadPreview(){if(props.page!=='versions'||!live.value||view.value!=='new-version'||!live.value.versionMeta?.canPublish)return;try{vPreview.value=await datasetApi.preview(live.value.ref,split.value);}catch(e){vPreview.value=null;liveError(e);}}
watch([split,view],loadPreview);
async function openVersion(v){try{const d=await datasetApi.version(live.value.ref,v.name);const {items,...card}=d;openModal('Version details',JSON.stringify({...card,photos_listed:items.length,deleted_since:items.filter(i=>i.deleted).length},null,2));}catch(e){liveError(e);}}
const splitWords={train:'Training',val:'Validation',test:'Test'};
// ── Train, connected (api/train.js): runs on the server's CPU ──
const runtime=ref(3600);const runView=ref(null);const runBusy=ref(false);let runTimer=null;
const trainModel=computed(()=>(live.value?.training?.models||[]).find(m=>m.label===architecture.value));
async function loadTrain(){if(!live.value)return;try{const t=await loadTraining(live.value);runtime.value=t.default_runtime||3600;const names=(t.versions||[]).map(v=>v.name);if(!names.includes(activeVersion.value))activeVersion.value=names[0]||'';if(!(t.models||[]).some(m=>m.label===architecture.value))architecture.value='RF-DETR';const m=(t.models||[]).find(x=>x.label===architecture.value);if(m&&!m.sizes.includes(size.value))size.value=m.sizes[0];}catch(e){liveError(e);}}
watch(architecture,()=>{const m=trainModel.value;if(m&&!m.sizes.includes(size.value))size.value=m.sizes[0];});
function reviewTraining(){if(engine.value!=='Custom training'){tell('Neural architecture search: coming soon');return;}if(!(Number(epochs.value)>=1&&Number(epochs.value)<=500)){tell('Epochs must be between 1 and 500');return;}openModal('Review training');}
async function startTraining(){runBusy.value=true;try{const r=await trainApi.start(live.value.ref,{version:activeVersion.value,model:trainModel.value?.value,size:size.value,epochs:Number(epochs.value),max_runtime:Number(runtime.value),key:startKey()});modal.value='';tell(`Run ${r.number} started on ${r.version}`);await loadTrain();await openRun(r.number);}catch(e){modal.value='';tell(e.message);}finally{runBusy.value=false;}}
async function openRun(number){clearTimeout(runTimer);try{runView.value=await trainApi.run(live.value.ref,number);view.value='run';if(runView.value.unfinished)runTimer=setTimeout(()=>{if(view.value==='run'&&props.page==='train')openRun(number);},5000);}catch(e){liveError(e);}}
function closeRun(){clearTimeout(runTimer);view.value='board';loadTrain();}
async function runAct(action){runBusy.value=true;try{await trainApi.act(live.value.ref,runView.value.number,action);await openRun(runView.value.number);loadTrain();}catch(e){tell(e.message);}finally{runBusy.value=false;}}
onUnmounted(()=>clearTimeout(runTimer));</script>
<template>
<div class="studio">
  <div v-if="!(LIVE_PAGES.includes(page)&&live)" class="studio-preview"><UiBadge tone="purple">Coming soon</UiBadge><span>Interactive frontend preview · Sample data · No jobs or requests run</span><label>Preview state <select v-model="stateMode"><option>Populated</option><option>Empty</option><option>Loading</option><option>Error</option></select></label></div>
  <div v-if="message" class="notice" role="status"><Check :size="17"/><span>{{ message }}</span><button class="icon-button" aria-label="Dismiss feedback" @click="message=''"><X :size="16"/></button></div>
  <div v-if="stateMode==='Loading'" class="panel preview-loading" aria-busy="true"><div/><div/><div/><p>Loading preview…</p><UiButton @click="stateMode='Populated'">Finish loading preview</UiButton></div>
  <div v-else-if="stateMode==='Error'" class="empty-state"><h2>We couldn’t load this view</h2><p>Simulated connection error. Your local draft is retained.</p><UiButton @click="stateMode='Populated'">Retry preview</UiButton></div>
  <template v-else-if="page==='annotate'">
    <template v-if="view==='board'"><div class="studio-actions"><div class="studio-tabs"><button :class="{active:!reviewMode}" @click="reviewMode=false">Board</button><button :class="{active:reviewMode}" @click="reviewMode=true;if(live&&page==='annotate')loadReview(live).catch(liveError)">Review queue <UiBadge>{{ live&&page==='annotate'?live.counts.to_approve:state.images.filter(i=>i.state==='In review').length }}</UiBadge></button><button @click="view='insights'">Insights</button></div><UiButton @click="emit('navigate','upload')"><Upload :size="16"/> Upload images</UiButton></div>
      <div v-if="reviewMode" class="media-grid"><button v-for="image in catalogVisible?state.images.filter(i=>i.state==='In review'&&(!(live&&page==='annotate')||i.batchId==='review')):[]" :key="image.id" class="media-card" @click="openEditor(image)"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.url" :alt="image.name"><strong>{{ image.name }}</strong><UiBadge>In review</UiBadge></button><div v-if="!catalogVisible||!state.images.some(i=>i.state==='In review')" class="empty-state"><h2>No images awaiting review</h2><p>Finish labeling or apply a sample auto-label preview.</p></div></div>
      <div v-else class="annotation-board"><section v-for="column in ['Unassigned','Annotating','In review','Dataset']" :key="column" :class="{'drop-ok':dragging&&dropOver===column&&batchColumn(dragging)!==column&&!dropRefusal(dragging,column),'drop-no':dragging&&dropOver===column&&!!dropRefusal(dragging,column)}" @dragover="dragOver(column,$event)" @dragleave="dropOver===column&&(dropOver='')" @drop.prevent="dropOn(column)"><h3>{{ column }} <UiBadge>{{ catalogVisible?state.batches.filter(b=>batchColumn(b)===column).length:0 }}</UiBadge></h3><button v-for="b in catalogVisible?state.batches.filter(b=>batchColumn(b)===column):[]" :key="b.id" :class="['batch-card',{dragging:dragging===b}]" :draggable="!!live" :title="live?'Drag to another column, or open it':''" @dragstart="dragStart(b,$event)" @dragend="dragEnd" @click="choicesMode='';chooseBatch(b)"><span v-if="b.code" class="batch-code">{{ b.code }}</span><strong>{{ b.name }}</strong><p>{{ b.count }} images · {{ b.group }}</p><div class="batch-progress"><span :style="{width:`${b.kind==='assignment'?(b.done||0)/Math.max(1,b.count)*100:state.images.filter(i=>i.batchId===b.id&&(i.shapes.length||i.noObjects)).length/Math.max(1,state.images.filter(i=>i.batchId===b.id).length)*100}%`}"/></div><footer><UiBadge>{{ b.assignee }}</UiBadge><span>Open batch →</span></footer></button><div v-if="!catalogVisible||!state.batches.some(b=>batchColumn(b)===column)" class="board-empty"><Images :size="27"/><p>{{ column==='Unassigned'?'No unassigned batches':column==='Annotating'?'Assign a batch to begin labeling':column==='In review'?'Labeled batches will appear here':'Approved batches appear here' }}</p><UiButton v-if="column==='Unassigned'" @click="emit('navigate','upload')">Upload</UiButton></div></section></div>
    </template>
    <AnnotationJob v-else-if="view==='job' && batch" :batch="batch" :state="state" @close="view='board';refreshLive().catch(liveError)" @choices="view='choices'" @edit="openEditor" @changed="refreshLive().catch(liveError)" @message="tell"/>
    <template v-else-if="view==='insights'"><UiButton @click="view='board'"><ArrowLeft :size="16"/> Back to board</UiButton><div class="metric-grid"><article><span>Images</span><strong>{{ insight.images }}</strong></article><article><span>Accepted</span><strong>{{ insight.accepted }}</strong></article><article><span>Annotations</span><strong>{{ insight.annotations }}</strong></article><article><span>To label</span><strong>{{ insight.toLabel }}</strong></article></div><section class="panel"><h2>Labeling progress</h2><p>{{ insight.live ? 'Counts of this project\'s photos and their labels.' : 'Counts reflect the local preview images.' }}</p><div class="distribution"><span :style="{width:`${insight.accepted/Math.max(1,insight.images)*100}%`}"/></div><p>{{ insight.accepted }} of {{ insight.images }} images accepted</p></section></template>
    <UnassignedMedia v-else-if="view==='choices' && batch" :key="batch.id" :start-mode="choicesMode" :batch="batch" :state="state" :project="project" @close="view='board'" @upload="emit('navigate','upload')" @rename="openModal('Rename batch',batch.name)" @edit="openEditor" @auto="view='auto'" @professional="openModal('Professional labeling')" @assigned="onAssigned"/>
    <template v-else-if="view==='auto'"><UiButton @click="view='choices'"><ArrowLeft :size="16"/> Labeling choices</UiButton><div class="auto-layout"><section class="panel"><h2>Classes & prompts</h2><p>Describe the objects you want to label.</p><div v-for="c in state.classes" :key="c.name" class="class-prompt"><span :style="{background:c.color}"/><strong>{{ c.name }}</strong></div><label class="field-label">Visual description<textarea v-model="prompt" class="text-input" rows="4"/></label><UiButton @click="emit('navigate','classes')">Manage classes</UiButton><h3 class="section-title">Preview image</h3><RoomArt/><p>Sample image, not an inference result.</p></section><section class="panel"><h2>Choose a model</h2><div class="studio-tabs"><button v-for="t in ['Foundation models','My models','My workflows']" :key="t" :class="{active:modelTab===t}" @click="modelTab=t">{{ t }}</button></div><label v-for="name in modelTab==='Foundation models'?['SAM 3 · masks','SAM 3 · polygons','SAM 2 · point guided']:modelTab==='My models'?state.models.map(m=>m.name):state.workflows.map(w=>w.name)" :key="name" class="model-choice"><input v-model="model" name="autolabel-model" type="radio" :value="name"><div><strong>{{ name }}</strong><p>Preview selection · Coming soon</p></div></label><p v-if="modelTab!=='Foundation models' && !(modelTab==='My models'?state.models:state.workflows).length">No local {{ modelTab==='My models'?'models':'workflows' }} yet. Choose a foundation model to explore.</p><div class="studio-actions"><UiButton variant="primary" @click="autoLabel"><Sparkles :size="16"/> Generate sample preview</UiButton></div><div v-if="autoReady" class="auto-result"><UiBadge tone="purple">Illustrative prediction</UiBadge><RoomArt/><p>Sample wall polygon shown for review. No model was called.</p><UiButton variant="primary" @click="applyAuto">Apply sample labels to review queue</UiButton></div></section></div></template>
