  <template v-else-if="page==='dataset'">
    <div class="studio-actions"><div class="search-field"><Search :size="17"/><input v-model="query" aria-label="Search dataset" placeholder="Search images…"></div><select v-model="filter" class="compact-select" aria-label="Filter image status"><option>All</option><option>Unlabeled</option><option>Annotating</option><option>In review</option><option>Accepted</option><option>Changes requested</option></select><UiButton @click="openModal('Dataset filters')"><Filter :size="15"/> Filters</UiButton><UiButton @click="grid=!grid">{{ grid?'List view':'Grid view' }}</UiButton><UiButton variant="primary" @click="emit('navigate','versions')">Create version</UiButton></div><div class="studio-actions"><label><input v-model="overlays" type="checkbox"> Show annotations</label><span>{{ picked.length }} selected</span><UiButton :disabled="!picked.length" @click="openModal('Tag selected images')">Add tag</UiButton><UiButton :disabled="!picked.length" @click="picked=[]">Clear selection</UiButton><UiButton v-if="live&&page==='dataset'&&state.dataset?.may?.delete" :disabled="!picked.length" @click="modalTargets=[...picked];openModal('Delete photos')"><Trash2 :size="14"/> Delete selected</UiButton><span v-if="live&&page==='dataset'&&state.dataset?.splitCounts">Training {{ state.dataset.splitCounts.train||0 }} · Validation {{ state.dataset.splitCounts.val||0 }} · Test {{ state.dataset.splitCounts.test||0 }} · Unassigned {{ state.dataset.splitCounts.unassigned||0 }}</span></div><div v-if="catalogVisible&&images.length" :class="['media-grid',{'media-list':!grid}]"><article v-for="image in images" :key="image.id" class="media-card"><div class="media-visual"><button @click="openEditor(image)"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.url" :alt="image.name"><span v-if="overlays&&(image.labels??image.shapes.length)" class="image-label">{{ image.labels??image.shapes.length }} labels</span></button><input v-model="picked" type="checkbox" :value="image.id" :aria-label="`Select ${image.name}`"></div><strong>{{ image.name }}</strong><UiBadge :tone="image.state==='Accepted'?'green':'neutral'">{{ image.state }}</UiBadge><p>{{ image.tags.join(', ') }}</p><template v-if="live&&page==='dataset'"><small>{{ image.group?(splitWords[image.split]||'Unassigned'):'Unassigned pool' }}{{ image.group?` · ${image.group}`:'' }}{{ image.golden?' · Golden':'' }}</small><div class="studio-actions"><UiButton v-if="state.dataset?.may?.golden" @click="toggleGolden(image)">{{ image.golden?'Leave golden set':'Make golden' }}</UiButton><UiButton v-if="state.dataset?.may?.delete" @click="modalTargets=[image.id];openModal('Delete photos')"><Trash2 :size="14"/> Delete</UiButton></div></template></article></div><div v-else class="empty-state"><Images :size="30"/><h2>No images here yet</h2><p>Upload images or clear the filters to explore the dataset.</p><UiButton @click="query='';filter='All';stateMode='Populated';resetFilters()">Clear filters</UiButton><UiButton @click="emit('navigate','upload')">Upload images</UiButton></div><footer class="studio-pagination"><template v-if="live&&page==='dataset'">{{ state.dataset?.total??0 }} images · page {{ state.dataset?.page||1 }} of {{ state.dataset?.pages||1 }} <UiButton :disabled="(state.dataset?.page||1)<=1" @click="refreshDataset(state.dataset.page-1)">Previous</UiButton> <UiButton :disabled="(state.dataset?.page||1)>=(state.dataset?.pages||1)" @click="refreshDataset(state.dataset.page+1)">Next</UiButton></template><template v-else>{{ catalogVisible?images.length:0 }} images · Preview collection</template></footer>
  </template>
  <template v-else-if="page==='classes'">
    <div class="studio-tabs"><button v-for="t in ['Classes','Tags']" :key="t" :class="{active:classTab===t}" @click="classTab=t">{{ t }} <UiBadge>{{ t==='Classes'?state.classes.length:state.tags.length }}</UiBadge></button></div><div class="studio-actions"><div class="search-field"><Search :size="17"/><input v-model="query" aria-label="Search definitions" placeholder="Search classes or tags…"></div><UiButton variant="primary" :disabled="classTab==='Classes'&&locked" @click="editing=-1;openModal('Add definition')"><Plus :size="16"/> Add {{ classTab==='Classes'?'class':'tag' }}</UiButton><label v-if="classTab==='Classes'"><input v-model="locked" type="checkbox"> Lock classes</label></div><div class="table-wrap"><table><thead><tr><th>{{ classTab==='Classes'?'Color':'Type' }}</th><th>Name</th><th>Usage</th><th>Modify</th></tr></thead><tbody><tr v-for="(c,i) in catalogVisible?(classTab==='Classes'?state.classes:state.tags.map(name=>({name}))).filter(c=>c.name.toLowerCase().includes(query.toLowerCase())):[]" :key="c.name"><td><span v-if="c.color" class="class-dot" :style="{background:c.color}"/><UiBadge v-else>Tag</UiBadge></td><td>{{ c.name }}</td><td>{{ classTab==='Classes'?counts.find(x=>x.name===c.name)?.count:state.images.filter(x=>x.tags.includes(c.name)).length }}</td><td><UiButton v-if="classTab==='Classes'" :disabled="locked" @click="editing=state.classes.findIndex(x=>x.name===c.name);color=c.color;openModal('Add definition',c.name)">Edit</UiButton><UiButton v-else @click="state.tags=state.tags.filter(t=>t!==c.name);state.images.forEach(x=>x.tags=x.tags.filter(t=>t!==c.name));tell('Tag removed')">Remove</UiButton></td></tr></tbody></table><div v-if="!catalogVisible" class="empty-state"><h3>No definitions yet</h3><p>Add a class or tag to organize the dataset.</p></div></div>
  </template>
  <template v-else-if="page==='versions'">
    <div v-if="view!=='new-version'"><div class="studio-actions"><p>Freeze a reproducible dataset configuration for training or evaluation.</p><UiButton v-if="!(live&&page==='versions')||state.versionMeta?.canPublish" variant="primary" :disabled="!!(live&&page==='versions'&&state.versionMeta?.refused)" @click="view='new-version';versionStep=1"><Plus :size="16"/> New version</UiButton></div><p v-if="live&&page==='versions'&&state.versionMeta?.refused" class="field-error">{{ state.versionMeta.refused }}</p><div v-if="catalogVisible&&state.versions.length" class="choice-grid"><template v-if="live&&page==='versions'"><article v-for="v in state.versions" :key="v.name" class="panel"><UiBadge tone="green">{{ v.kind_label }}</UiBadge><h2>{{ v.title||v.name }}</h2><p>{{ v.photos }} photos · {{ v.name }}</p><p>Training {{ v.split_counts.train||0 }} · Validation {{ v.split_counts.val||0 }} · Test {{ v.split_counts.test||0 }}</p><p>Resize: {{ v.recipe.resize?`${v.recipe.resize} × ${v.recipe.resize}`:'Original' }} · Auto-orient: On{{ v.recipe.augment?' · Flip and brightness':'' }}</p><p v-if="v.untrainable" class="field-error">{{ v.untrainable }}</p><p v-if="v.deleted">{{ v.deleted }} of its photos were deleted on request since.</p><UiButton :disabled="!state.versionMeta?.kinds?.find(k=>k.value===v.kind)?.training||!!v.untrainable" @click="activeVersion=v.name;emit('navigate','train')">Use for training</UiButton><UiButton @click="openVersion(v)">View configuration</UiButton><a class="button button--secondary" :href="v.manifest" download>Manifest</a></article></template><template v-else><article v-for="v in state.versions" :key="v.id" class="panel"><UiBadge tone="green">Local configuration</UiBadge><h2>{{ v.name }}</h2><p>{{ v.images }} accepted images · {{ v.split }}</p><p>Resize: {{ v.resize }} · Auto-orient: {{ v.orient?'On':'Off' }}</p><UiButton @click="activeVersion=String(v.id);emit('navigate','train')">Use for training</UiButton><UiButton @click="openModal('Version details',JSON.stringify(v,null,2))">View configuration</UiButton></article></template></div><div v-else class="empty-state"><Layers :size="32"/><h2>No versions yet</h2><p>Create your first version from accepted images.</p><UiButton variant="primary" @click="view='new-version';versionStep=1">Create a version</UiButton></div></div>
    <div v-else class="version-builder"><aside><h3>New version</h3><button v-for="(label,i) in ['Source images','Split rules','Preprocessing','Augmentation','Review & create']" :key="label" :class="{active:versionStep===i+1}" @click="versionStep=i+1"><span>{{ i+1 }}</span>{{ label }}</button></aside><section class="panel"><template v-if="versionStep===1"><h2>Source images</h2><p v-if="live&&page==='versions'">{{ vPreview?`${vPreview.photos} photos with an approved label can go into this version (${vPreview.new} new since ${vPreview.latest||'the start'}).`:'Counting…' }}</p><p v-else>{{ accepted }} accepted images from {{ state.images.length }} total images.</p><label class="field-label">Version name<input v-model="versionName" class="text-input" maxlength="80"></label><p>Only accepted labeled images are eligible. No-object examples remain excluded from training versions under the existing workflow.</p><UiButton @click="emit('navigate','dataset')">Inspect dataset</UiButton></template><template v-else-if="versionStep===2"><h2>Train / validation / test</h2><template v-if="live&&page==='versions'"><p>Every photo of one home or group stays on the same side. The side is fixed when the photo arrives (about 70 / 15 / 15), never chosen by hand. This is what the version will hold:</p><div class="split-bar"><span>Train {{ vPreview?.split_counts?.train||0 }}</span><span>Valid {{ vPreview?.split_counts?.val||0 }}</span><span>Test {{ vPreview?.split_counts?.test||0 }}</span></div></template><template v-else><p>Related home/group images stay together. The proportions below are illustrative; no image split is computed in this prototype.</p><div class="split-bar"><span>Train ~70%</span><span>Valid ~15%</span><span>Test ~15%</span></div></template><label class="field-label">Version purpose<select v-model="split" class="text-input"><option value="train_val">Training / validation</option><option value="test">Test evaluation only</option><option value="golden">Golden evaluation only</option><option value="smoke">Smoke check</option></select></label><p>Test and golden versions must not be used for training.</p></template><template v-else-if="versionStep===3"><h2>Preprocessing</h2><p>Configure how images are prepared before training.</p><label class="setting-row"><input v-model="orient" type="checkbox" :disabled="live&&page==='versions'"> Auto-orient images<template v-if="live&&page==='versions'"> (always: photos are turned upright when they arrive)</template></label><label class="setting-row"><input v-model="resize" type="checkbox"> Resize images</label><label v-if="resize" class="field-label">Target size<select v-model="dimension" class="text-input"><option :value="512">512 × 512</option><option :value="640">640 × 640</option><option :value="1024">1024 × 1024</option></select></label><RoomArt class="version-preview"/><p v-if="live&&page==='versions'">The size is used when a model trains on this version, rounded to the nearest size that model accepts.</p><p v-else>Illustration only; image processing is not connected.</p></template><template v-else-if="versionStep===4"><h2>Augmentation</h2><p>Explore training-only transformations. Validation and test images remain unaugmented.</p><label class="setting-row"><input v-model="augmentation" type="checkbox"> Horizontal flip and brightness variation</label><div class="augmentation-previews"><RoomArt/><RoomArt :style="{transform:'scaleX(-1)',filter:'brightness(1.1)'}"/></div></template><template v-else><h2>Review version</h2><dl class="summary-list"><dt>Name</dt><dd>{{ versionName }}</dd><dt>Source</dt><dd>{{ live&&page==='versions'?`${vPreview?.photos??0} photos with an approved label`:`${accepted} accepted images` }}</dd><dt>Purpose</dt><dd>{{ split }}</dd><dt>Preprocessing</dt><dd>{{ orient?'Auto-orient · ':'' }}{{ resize?`${dimension} × ${dimension}`:'Original size' }}</dd><dt>Augmentation</dt><dd>{{ augmentation?'Flip and brightness (training only)':'None' }}</dd></dl><template v-if="live&&page==='versions'&&vPreview"><p>{{ vPreview.photos }} photos: {{ vPreview.new }} new, {{ vPreview.kept }} kept from {{ vPreview.latest||'no earlier version' }}.</p><p v-if="vPreview.unchanged" class="field-error">Nothing changed since {{ vPreview.latest }}: the same photos with the same labels.</p><p v-if="vPreview.untrainable" class="field-error">{{ vPreview.untrainable }}</p><p v-if="!vPreview.photos" class="field-error">No photo can go into this version yet.</p></template><UiBadge v-if="!(live&&page==='versions')">Coming soon</UiBadge></template><div class="wizard-footer"><UiButton @click="versionStep>1?versionStep--:view='board'">{{ versionStep>1?'Back':'Cancel' }}</UiButton><UiButton v-if="versionStep<5" variant="primary" @click="versionStep++">Continue</UiButton><UiButton v-else variant="primary" :disabled="vBusy||!!(live&&page==='versions'&&vPreview&&(vPreview.unchanged||!vPreview.photos))" @click="makeVersion">{{ live&&page==='versions'?(vBusy?'Creating…':'Create version'):'Create local version' }}</UiButton></div></section></div>
  </template>
  <AnalyticsPage v-else-if="page==='analytics'&&live" :project-ref="project.ref"/>
  <template v-else-if="page==='analytics'"><div class="studio-actions"><p>Dataset analytics · Calculated from local preview annotations</p><UiButton @click="tell('Local counts refreshed')"><RefreshCw :size="15"/> Refresh</UiButton><UiButton @click="downloadCsv"><Download :size="15"/> Download CSV</UiButton></div><div class="metric-grid"><article><span>Images</span><strong>{{ catalogVisible?state.images.length:0 }}</strong><small>{{ state.images.filter(i=>!i.shapes.length).length }} without annotations</small></article><article><span>Annotations</span><strong>{{ catalogVisible?annotations:0 }}</strong><small>{{ state.classes.length }} classes</small></article><article><span>Accepted</span><strong>{{ catalogVisible?accepted:0 }}</strong><small>Ready for dataset review</small></article><article><span>Preview canvas</span><strong>600 × 300</strong><small>Illustrative dimensions</small></article></div><section class="panel"><h2>Class distribution</h2><p>Counts of annotations in this local collection.</p><div v-for="c in counts" :key="c.name" class="class-bar"><span>{{ c.name }}</span><div><i :style="{width:`${catalogVisible?c.count/Math.max(1,annotations)*100:0}%`,background:c.color}"/></div><strong>{{ catalogVisible?c.count:0 }}</strong></div></section><div class="foundation-grid analytics-bottom"><section class="panel"><h2>Review readiness</h2><p>Keep a clear separation between labels awaiting review and accepted data.</p><div v-for="s in ['Unlabeled','Annotating','In review','Accepted','Changes requested']" :key="s" class="stat-row"><span>{{ s }}</span><UiBadge>{{ state.images.filter(i=>i.state===s).length }}</UiBadge></div></section><section class="panel"><h2>Dimension insights</h2><div class="dimension-plot"><span>300 px</span><i/><span>600 px</span></div><p>Synthetic preview canvas shown. Production image-size statistics require a backend contract; these are not measurements of uploaded originals.</p></section></div></template>
  <ModelsPage v-else-if="page==='models'&&live" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <template v-else-if="page==='models'"><div class="studio-tabs"><button v-for="t in ['My models','Open source models','Compare','Model monitoring']" :key="t" :class="{active:modelView===t}" @click="modelView=t">{{ t }}</button></div><template v-if="modelView==='My models'"><div class="studio-actions"><UiButton variant="primary" @click="emit('navigate','train')">Train a model</UiButton><UiButton @click="openModal('Upload weights')"><Upload :size="15"/> Upload weights</UiButton></div><div v-if="catalogVisible&&state.models.length" class="choice-grid"><article v-for="m in state.models" :key="m.id" class="panel"><Box :size="25"/><h2>{{ m.name }}</h2><p>{{ m.status }}</p><UiBadge tone="purple">Simulated metrics</UiBadge><p>Accuracy {{ Math.round(m.accuracy*100) }}% · 12 ms sample latency</p><UiButton @click="model=m.name;emit('navigate','test')">Test model</UiButton><UiButton @click="emit('navigate','deploy')">Deployment options</UiButton></article></div><div v-else class="model-empty"><Box :size="42"/><h2>No trained models yet</h2><p>Create a project and explore a simulated training run, or preview custom weight import.</p><UiButton variant="primary" @click="emit('navigate','train')">Train a model</UiButton></div></template><template v-else-if="modelView==='Open source models'"><div class="studio-actions"><div class="search-field"><Search :size="16"/><input v-model="query" aria-label="Search models" placeholder="Search models…"></div><select v-model="taskFilter" class="compact-select" aria-label="Model task"><option>All tasks</option><option>Instance segmentation</option><option>Text prompting</option><option>Classification</option><option>Object detection</option><option>OCR</option></select></div><div class="model-catalog"><article v-for="m in catalogVisible?filteredModels:[]" :key="m.name" class="panel"><Box :size="25"/><UiBadge>{{ m.task }}</UiBadge><h2>{{ m.name }}</h2><p>{{ m.description }}</p><UiButton @click="model=m.name;openModal('Use model')">Use model</UiButton></article></div><p v-if="!filteredModels.length||!catalogVisible">No models match your selection.</p></template><template v-else-if="modelView==='Compare'"><div class="panel"><h2>Accuracy vs. latency</h2><p>Illustrative comparison. These points are not model measurements.</p><svg class="comparison-chart" viewBox="0 0 600 240" role="img" aria-label="Illustrative accuracy versus latency chart"><path d="M50 20V200H570" fill="none" stroke="#c9c6d0"/><path d="M70 180L180 120L290 80L410 55L550 35" fill="none" stroke="#9c74ec" stroke-width="4"/><circle v-for="p in [[70,180],[180,120],[290,80],[410,55],[550,35]]" :key="p.join()" :cx="p[0]" :cy="p[1]" r="6" fill="#9c74ec"/><text x="250" y="230" fill="#8a8095" font-size="12">Latency (illustrative)</text></svg><UiButton @click="emit('navigate','train')">Add a model to compare</UiButton></div></template><section v-else class="panel"><h2>Model monitoring</h2><p>Preview the signals that help you assess deployed models.</p><div class="metric-grid"><article><span>Requests</span><strong>—</strong></article><article><span>Error rate</span><strong>—</strong></article><article><span>Latency</span><strong>—</strong></article></div><UiButton @click="openModal('Monitoring setup')">Configure monitoring</UiButton></section></template>
  <template v-else-if="page==='train'&&view==='run'&&runView"><UiButton @click="closeRun"><ArrowLeft :size="16"/> Back to training</UiButton><section class="panel training-config"><h2>Run {{ runView.number }} · {{ runView.trains.summary }}</h2><p><UiBadge :tone="runView.state==='succeeded'?'green':'purple'">{{ runView.state_label }}</UiBadge> {{ runView.version_title?`${runView.version_title} · `:'' }}{{ runView.version }} · started by {{ runView.by }} · {{ new Date(runView.created_at).toLocaleString() }}</p><template v-if="progressLine(runView.progress)"><div class="distribution"><span :style="{width:`${progressLine(runView.progress).share*100}%`}"/></div><p>{{ progressLine(runView.progress).text }}</p></template><p v-else-if="runView.unfinished">{{ runView.state==='queued'?'Waiting for the CPU: one run trains at a time.':'Starting…' }}</p><p v-if="runView.failure" class="field-error">{{ runView.failure }}</p><dl v-if="Object.keys(runView.final_metrics||{}).length" class="summary-list"><template v-for="(value,name) in runView.final_metrics" :key="name"><dt>{{ name }}</dt><dd>{{ typeof value==='number'?value.toFixed(4):value }}</dd></template></dl><p v-if="runView.model">It made model {{ runView.model.version }}.</p><div class="studio-actions"><UiButton v-if="runView.may.cancel" :disabled="runBusy" @click="runAct('cancel')">Cancel run</UiButton><UiButton v-if="runView.may.retry" variant="primary" :disabled="runBusy" @click="runAct('retry')">Retry</UiButton><a v-for="a in runView.attempts" :key="a.number" class="button button--secondary" :href="a.log" download>Log of attempt {{ a.number }}</a></div><h3>Log</h3><pre class="code-block">{{ runView.log||'Nothing written yet.' }}</pre></section></template><template v-else-if="page==='train'"><h2>Select a training engine</h2><p class="section-description">Choose your configuration, review the dataset, and explore the resulting job screen.</p><div class="choice-grid"><button :class="{chosen:engine==='Custom training'}" @click="engine='Custom training'"><Settings2 :size="26"/><h3>Custom training</h3><p>Select architecture, model size and training settings.</p></button><button :class="{chosen:engine==='Neural architecture search'}" @click="engine='Neural architecture search'"><Sparkles :size="26"/><h3>Neural architecture search</h3><p>Explore a search across model sizes and accuracy/latency targets.</p><UiBadge>Coming soon</UiBadge></button></div><section class="panel training-config"><h2>Training configuration</h2><div class="form-grid"><label class="field-label">Dataset version<select v-if="live&&page==='train'" v-model="activeVersion" class="text-input"><option v-if="!state.training?.versions?.length" value="">No version can be trained yet</option><option v-for="v in state.training?.versions||[]" :key="v.name" :value="v.name">{{ v.title?`${v.title} · `:'' }}{{ v.name }} · {{ v.photos }} photos</option></select><select v-else v-model="activeVersion" class="text-input"><option value="">Sample version (preview only)</option><option v-for="v in state.versions" :key="v.id" :value="String(v.id)" :disabled="['test','golden'].includes(v.split)">{{ v.name }} · {{ v.split }}</option></select></label><label class="field-label">Architecture<select v-model="architecture" class="text-input"><option>RF-DETR</option><option v-if="live&&page==='train'">SegFormer-B0</option><option value="YOLO" :disabled="live&&page==='train'">YOLO{{ live&&page==='train'?' (Coming soon)':'' }}</option><option value="Custom architecture" :disabled="live&&page==='train'">Custom architecture{{ live&&page==='train'?' (Coming soon)':'' }}</option></select></label><label class="field-label">Model size<select v-model="size" class="text-input"><template v-if="live&&page==='train'&&trainModel"><option v-for="s in trainModel.sizes" :key="s" :value="s">{{ s }}{{ trainModel.slow.includes(s)?' (slow on a CPU: hours)':'' }}</option></template><template v-else><option>Nano</option><option>Small</option><option>Medium</option><option>Large</option></template></select></label><label class="field-label">Epochs<input v-model="epochs" class="text-input" type="number" min="1" max="500"></label><label v-if="live&&page==='train'" class="field-label">Maximum runtime<select v-model="runtime" class="text-input"><option v-for="r in state.training?.runtimes||[]" :key="r.value" :value="r.value">{{ r.label }}</option></select></label></div><template v-if="live&&page==='train'"><p>Runs on this server's CPU and stops at its time limit. Test and golden versions are never trained on.{{ trainModel?.research_only?' SegFormer-B0 is for research and evaluation only: a model trained from it is never released to an app.':'' }}{{ trainModel?.slow?.includes(size)?' This size is slow on a CPU: expect hours.':'' }}</p><p v-if="state.training?.refused" class="field-error">{{ state.training.refused }}</p><p v-else-if="state.training?.no_version" class="field-error">{{ state.training.no_version }}</p><p v-else-if="state.training&&!state.training.can_train" class="field-error">Your role in this project does not let you start a run.</p></template><p v-else>Test and golden versions are unavailable for training. No compute, credits or infrastructure will be used.</p><UiButton variant="primary" :disabled="live&&page==='train'&&(!!state.training?.refused||!state.training?.can_train||!activeVersion)" @click="live&&page==='train'?reviewTraining():(Number(epochs)>=1&&Number(epochs)<=500?openModal('Review training'):tell('Epochs must be between 1 and 500'))">Review training configuration</UiButton></section><section v-if="live&&page==='train'&&state.training?.runs?.length" class="panel training-config"><h2>Runs</h2><div v-for="r in state.training.runs" :key="r.number" class="stat-row"><strong>Run {{ r.number }} · {{ r.trains.summary }} · {{ r.version }}</strong><UiBadge :tone="r.state==='succeeded'?'green':'purple'">{{ r.state_label }}</UiBadge><UiButton @click="openRun(r.number)">View run</UiButton></div></section><section v-else-if="state.runs.length" class="panel training-config"><h2>Preview runs</h2><div v-for="r in state.runs" :key="r.id" class="stat-row"><strong>{{ r.name }}</strong><UiBadge tone="purple">{{ r.status }}</UiBadge><UiButton @click="emit('navigate','models')">View result</UiButton></div></section></template>
  <template v-else-if="page==='nas'"><section class="nas-hero"><div><UiBadge tone="purple">NEURAL ARCHITECTURE SEARCH</UiBadge><h2>Find the right balance<br>of speed and accuracy.</h2><p>Explore a search configuration and inspect a clearly labeled sample result.</p><UiButton variant="primary" @click="engine='Neural architecture search';emit('navigate','train')"><Plus :size="17"/> New NAS run</UiButton></div><div class="panel"><h3>Accuracy / latency tradeoff</h3><svg class="comparison-chart" viewBox="0 0 500 220" role="img" aria-label="Illustrative model search curve"><path d="M30 20V190H480" fill="none" stroke="#cfc8df"/><path d="M45 170Q100 70 460 30" fill="none" stroke="#8b5cf6" stroke-width="4"/><text x="150" y="215" font-size="12" fill="#8a8095">Illustrative preview, not measurements</text></svg></div></section><div class="empty-state"><h2>{{ state.runs.length?'Preview runs available':'No architecture searches yet' }}</h2><p>Real search execution is not connected.</p><UiButton @click="emit('navigate','train')">View training configurations</UiButton></div></template>
  <TestPage v-else-if="page==='test'&&live" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <template v-else-if="page==='test'"><div class="test-layout"><section class="panel"><h2>Test a model</h2><label class="field-label">Model<select v-model="model" class="text-input"><option>SAM 3 · masks</option><option v-for="m in state.models" :key="m.id">{{ m.name }}</option></select></label><div class="test-input"><RoomArt v-if="testSample"/><Images v-else :size="45"/><UiButton @click="testSample=true;resultReady=false">{{ testSample?'Replace with sample image':'Choose sample image' }}</UiButton></div><label class="field-label">Confidence threshold: {{ confidence }}<input v-model="confidence" type="range" min="0" max="1" step="0.05"></label><UiButton variant="primary" :disabled="!testSample" @click="resultReady=true">Show sample prediction</UiButton></section><section class="panel"><h2>Prediction results</h2><template v-if="resultReady"><UiBadge tone="purple">Simulated output</UiBadge><RoomArt/><div v-if="Number(confidence)<=0.94" class="stat-row"><strong>wall</strong><UiBadge>0.94 sample confidence</UiBadge></div><p v-else>No sample detections above this threshold.</p><pre>{{ JSON.stringify({preview:true,class:'wall',confidence:0.94,threshold:Number(confidence)},null,2) }}</pre><p>No model was called; results are fixed sample data.</p></template><div v-else class="empty-state"><h3>Ready when you are</h3><p>Select a sample image to explore the result layout.</p></div></section></div></template>
  <DeployPage v-else-if="page==='deploy'&&live" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <template v-else-if="page==='deploy'"><section class="panel"><div class="studio-actions"><h2>Developer quick start</h2><UiBadge>Preview model configuration</UiBadge><UiButton @click="openModal('Deployment settings')">Model settings</UiButton></div><div class="deploy-layout"><nav><button v-for="t in ['Cloud API','MCP','Batch processing','Dedicated deployment']" :key="t" :class="{active:deployMode===t}" @click="deployMode=t">{{ t }}</button></nav><div><h3>{{ deployMode }}</h3><p>Connection setup and execution require an existing approved backend contract.</p><div class="studio-tabs"><button v-for="l in ['Python','JavaScript','HTTP / cURL']" :key="l" :class="{active:codeLang===l}" @click="codeLang=l">{{ l }}</button></div><pre class="code-block">{{ code }}</pre><UiButton @click="copyCode"><Copy :size="15"/> Copy illustrative snippet</UiButton><UiButton @click="openModal('Deployment configuration')">Configure {{ deployMode }}</UiButton></div></div></section><section class="panel training-config"><h2>Dependent workflows</h2><p v-if="!state.workflows.length">No workflows connected in this preview.</p><div v-for="w in state.workflows" :key="w.name" class="stat-row"><strong>{{ w.name }}</strong><UiBadge>Local draft</UiBadge></div><UiButton @click="openModal('Create workflow')">Create workflow draft</UiButton></section></template>
  <template v-else-if="page==='active'"><section class="nas-hero"><div><UiBadge tone="purple">ACTIVE LEARNING</UiBadge><h2>Improve your model<br>with production data.</h2><p>Preview collection conditions, review incoming samples, and decide what enters the next dataset.</p><UiButton variant="primary" @click="openModal('Active learning rules')">Configure active learning</UiButton></div><div class="learning-flow"><article>1. Live inference data</article><span>↓</span><article>2. Apply confidence & class conditions</article><span>↓</span><article>3. Review collected images</article><span>↓</span><article>4. Add to dataset and retrain</article></div></section><section v-if="state.activeRules.length" class="panel"><h2>Local rule drafts</h2><div v-for="(r,i) in state.activeRules" :key="i" class="stat-row"><span>{{ r.class }} · confidence below {{ r.confidence }} · limit {{ r.limit }}</span><UiBadge>Not active</UiBadge><UiButton @click="state.activeRules.splice(i,1)">Remove</UiButton></div></section></template>
  <AnnotationEditor v-if="editor" :state="state" :batch-id="['job','choices'].includes(view)?batch?.id:(page==='dataset'&&live?'dataset':(reviewMode&&live&&page==='annotate'?'review':null))" @close="editor=false;page==='dataset'?refreshDataset():refreshLive().catch(liveError)"/>
  <UiDialog :open="!!moveDialog" :title="moveDialog?.title" @close="moveDialog=null"><template v-if="moveDialog"><p class="dialog-description">{{ moveDialog.text }}</p><label v-if="moveDialog.reason" class="field-label">Reason<textarea v-model="moveReason" class="text-input" rows="3" maxlength="1000"/></label><p v-if="moveDialog.error" class="field-error" role="alert">{{ moveDialog.error }}</p><div class="dialog-actions"><UiButton @click="moveDialog=null">Cancel</UiButton><UiButton variant="primary" :disabled="moveBusy||(moveDialog.reason&&!moveReason.trim())" @click="confirmMove">{{ moveDialog.button }}</UiButton></div></template></UiDialog><UiDialog :open="!!modal" :title="modal==='Add definition'?`${editing>=0?'Edit':'Add'} ${classTab==='Classes'?'class':'tag'}`:modal" @close="modal=''">
    <p v-if="error" class="field-error" role="alert">{{ error }}</p>
    <template v-if="modal==='Add definition'"><label class="field-label">Name<input v-model="draft" class="text-input" maxlength="60"></label><label v-if="classTab==='Classes'" class="field-label">Color<input v-model="color" type="color"></label><div class="dialog-actions"><UiButton @click="modal=''">Cancel</UiButton><UiButton variant="primary" @click="addClass">Save locally</UiButton></div></template>
    <template v-else-if="modal==='Rename batch'"><label class="field-label">Batch name<input v-model="draft" class="text-input"></label><UiButton @click="renameBatch">Save name</UiButton></template>
    <template v-else-if="modal==='Assign labeling'"><label class="field-label">Assign to<select v-model="assignee" class="text-input"><option>Demo labeller</option><option>Demo reviewer</option><option>Me</option></select></label><label class="field-label">Instructions<textarea v-model="draft" class="text-input" placeholder="Outline walls, windows and doors; review all corners."/></label><p class="dialog-description">No invitation or notification will be sent.</p><div class="dialog-actions"><UiButton variant="primary" @click="batch.instructions=draft;batch.assignee=assignee;batch.status='Annotating';modal='';view='board';tell('Sample assignment saved')">Assign locally</UiButton></div></template>
    <template v-else-if="modal==='Professional labeling'"><label class="field-label">Labeling brief<textarea v-model="draft" class="text-input" rows="4" placeholder="Describe classes, quality requirements and review criteria."/></label><p class="dialog-description">Coming soon. No vendor is contacted and no images leave this browser.</p><UiButton @click="draft.trim()?(batch.brief=draft.trim(),modal='',tell('Labeling brief preview saved')):error='Enter a labeling brief.'">Save local brief</UiButton></template>
    <template v-else-if="modal==='Tag selected images'"><label class="field-label">Tag<input v-model="draft" class="text-input"></label><UiButton @click="tagPicked">Apply to {{ picked.length }} images</UiButton></template>
    <template v-else-if="modal==='Dataset filters'&&live&&page==='dataset'"><label class="field-label">Status<select v-model="filter" class="text-input"><option>All</option><option>Unlabeled</option><option>Annotating</option><option>In review</option><option>Changes requested</option><option>Accepted</option></select></label><label class="field-label">Split<select v-model="dsFilters.split" class="text-input"><option value="">All</option><option value="train">Training</option><option value="val">Validation</option><option value="test">Test</option><option value="unassigned">Unassigned pool</option></select></label><label class="field-label">Home / group<input v-model="dsFilters.group" class="text-input" maxlength="200"></label><label class="field-label">Image source<select v-model="dsFilters.origin" class="text-input"><option value="">All</option><option value="development">Development / test images</option><option value="customer">Customer images</option></select></label><label class="field-label">Golden set<select v-model="dsFilters.golden" class="text-input"><option value="">All</option><option value="true">In the golden set</option><option value="false">Not golden</option></select></label><label class="field-label">Tag<input v-model="dsFilters.tag" class="text-input" maxlength="40"></label><div class="dialog-actions"><UiButton @click="resetFilters();modal=''">Clear</UiButton><UiButton variant="primary" @click="refreshDataset(1);modal=''">Apply filter</UiButton></div></template><template v-else-if="modal==='Dataset filters'"><label class="field-label">Status<select v-model="filter" class="text-input"><option>All</option><option>Unlabeled</option><option>In review</option><option>Accepted</option></select></label><p class="dialog-description">Filter the current local preview collection.</p><UiButton @click="modal=''">Apply filter</UiButton></template><template v-else-if="modal==='Delete photos'"><p class="dialog-description">{{ modalTargets.length }} photo{{ modalTargets.length===1?'':'s' }} will be deleted: the stored copy and the records that brought it go, and it can never be taken in again. Versions that already hold it keep it, and are listed with the deletion.</p><label class="field-label">Reason (required)<textarea v-model="draft" class="text-input" rows="3" maxlength="500" placeholder="For example: the customer asked for it."/></label><div class="dialog-actions"><UiButton @click="modal=''">Cancel</UiButton><UiButton variant="primary" @click="deleteTargets">Delete</UiButton></div></template>
    <template v-else-if="modal==='Version details'"><pre>{{ draft }}</pre><UiButton @click="modal=''">Close</UiButton></template>
    <template v-else-if="modal==='Review training'"><dl class="summary-list"><dt>Engine</dt><dd>{{ engine }}</dd><dt>Model</dt><dd>{{ architecture }} {{ size }}</dd><dt>Epochs</dt><dd>{{ epochs }}</dd><dt>Version</dt><dd>{{ live&&page==='train'?activeVersion:(state.versions.find(v=>String(v.id)===activeVersion)?.name||'Sample version') }}</dd><template v-if="live&&page==='train'"><dt>Maximum runtime</dt><dd>{{ (state.training?.runtimes||[]).find(r=>r.value===Number(runtime))?.label }}</dd><dt>Runs on</dt><dd>This server's CPU</dd></template></dl><p class="dialog-description">{{ live&&page==='train'?'Starts a training run on this server’s CPU. It stops at the time limit you chose.':'This action only adds a simulated result. No training, deployment or billing action occurs.' }}</p><div class="dialog-actions"><UiButton @click="modal=''">Back</UiButton><UiButton variant="primary" :disabled="runBusy" @click="live&&page==='train'?startTraining():train()">{{ live&&page==='train'?(runBusy?'Starting…':'Start training'):'Simulate training result' }}</UiButton></div></template>
    <template v-else-if="modal==='Upload weights'"><label class="field-label">Model name<input v-model="draft" class="text-input" placeholder="My custom model"></label><label class="field-label">Format<select class="text-input"><option>PyTorch (.pt)</option><option>ONNX (.onnx)</option><option>Safetensors</option></select></label><p class="dialog-description">Coming soon. This previews model registration; no weight file is uploaded.</p><UiButton @click="draft.trim()?(state.models.push({id:Date.now(),name:draft,status:'Weight import preview',accuracy:0}),modal='',tell('Weight import draft added')):error='Enter a model name.'">Add import draft</UiButton></template>
    <template v-else-if="modal==='Use model'"><h3>{{ model }}</h3><p class="dialog-description">Choose where to explore this model. No inference will run.</p><div class="dialog-actions"><UiButton @click="modal='';emit('navigate','test')">Test preview</UiButton><UiButton variant="primary" @click="goAuto()">Auto-label preview</UiButton></div></template>
    <template v-else-if="modal==='Active learning rules'"><label class="field-label">Source<select v-model="source" class="text-input"><option>Production model</option><option>Staging model</option></select></label><label class="field-label">Class<select v-model="ruleClass" class="text-input"><option v-for="c in state.classes" :key="c.name">{{ c.name }}</option></select></label><label class="field-label">Confidence below<input v-model="activeConfidence" type="number" min="0" max="1" step=".05" class="text-input"></label><label class="field-label">Maximum images<input v-model="activeLimit" type="number" min="1" max="10000" class="text-input"></label><p class="dialog-description">Saving creates an inactive local draft, not a production collector.</p><UiButton @click="Number(activeLimit)>0&&Number(activeConfidence)>=0&&Number(activeConfidence)<=1?(state.activeRules.push({source,class:ruleClass,limit:activeLimit,confidence:activeConfidence}),modal='',tell('Inactive collection rule saved')):error='Enter a positive limit and confidence from 0 to 1.'">Save rule draft</UiButton></template>
    <template v-else-if="modal==='Create workflow'"><label class="field-label">Workflow name<input v-model="draft" class="text-input" placeholder="Detect and review walls"></label><UiButton @click="draft.trim()?(state.workflows.push({name:draft.trim()}),modal='',tell('Workflow draft added')):error='Enter a workflow name.'">Create local draft</UiButton></template>
    <template v-else><label class="field-label">Configuration name<input v-model="draft" class="text-input" placeholder="e.g. Staging preview"></label><label class="field-label">Environment<select class="text-input"><option>Staging</option><option>Production (preview only)</option></select></label><p class="dialog-description">Coming soon. No endpoint, credential, monitoring rule or deployment is created.</p><UiButton @click="draft.trim()?(modal='',tell('Configuration preview recorded')):error='Enter a configuration name.'">Save local configuration</UiButton></template>
  </UiDialog>
</div>
</template>
